import java.util.Scanner;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class Main {
    public static void main(String[] args) {
        _538A_CuttingBanner.run();
    }
}

class _538A_CuttingBanner {
    private static final String WORD = "CODEFORCES";

    public static void run() {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();
        boolean ok = doit(s);
        System.out.println(ok ? "YES" : "NO");
        scanner.close();
    }

    private static boolean doit(String word) {
        if (word.startsWith(WORD) || word.endsWith(WORD)) return true;
        for (int i = 1; i < WORD.length(); i++) {
            String pat = "^" + WORD.substring(0, i) + ".*" + WORD.substring(i) + "$";
            Pattern pattern = Pattern.compile(pat);
            Matcher matcher = pattern.matcher(word);
            if (matcher.matches()) return true;
        }
        return false;
    }
}

